<script setup lang="ts">import{reactive}from'vue';import{Head,router}from'@inertiajs/vue3';import{route}from'ziggy-js';import{usePermissions}from'../../composables/usePermissions';interface Causa{causa:string;confianza:string}interface Respuesta{resumen:string;posibles_causas:Causa[];prioridad:string;riesgos:string[];recomendacion_inmediata:string;especialidad_recomendada:string;servicios_sugeridos:string[];preguntas_adicionales:string[];observaciones_mecanico:string;advertencia:string}interface Consulta{id:string;cliente:string;vehiculo:string;respuesta:Respuesta;estado:string;prioridad:string;simulada:boolean;especialidad?:string;citaId?:string;ordenId?:string;revisiones:unknown[]}const props=defineProps<{consulta:Consulta;servicios:{id:string;nombre:string}[]}>();const{can}=usePermissions();const revision=reactive({estado:'confirmada',observaciones:'',resumenAjustado:props.consulta.respuesta.resumen});function revisar(){router.post(route('ia.revisar',props.consulta.id),revision,{preserveScroll:true})}</script>
<template><Head title="Orientación IA"/><UDashboardPanel><template #header><UDashboardNavbar title="Orientación inicial"><template #right><div class="flex gap-2"><UBadge v-if="consulta.simulada" color="neutral">Modo simulado</UBadge><UBadge :color="['alta','critica'].includes(consulta.prioridad)?'error':'primary'">{{consulta.prioridad}}</UBadge></div></template></UDashboardNavbar></template><template #body><UAlert color="warning" icon="i-lucide-triangle-alert" title="Advertencia obligatoria" :description="consulta.respuesta.advertencia"/><div class="grid gap-6 xl:grid-cols-3"><div class="space-y-6 xl:col-span-2"><UCard><template #header><div><p class="text-sm text-muted">{{consulta.cliente}} · {{consulta.vehiculo}}</p><h2 class="text-xl font-semibold">Resumen</h2></div></template><p>{{consulta.respuesta.resumen}}</p></UCard><UCard><template #header><h2 class="font-semibold">Posibles causas</h2></template><div v-for="c in consulta.respuesta.posibles_causas" :key="c.causa" class="flex justify-between gap-3 border-b border-default py-3 last:border-0"><span>{{c.causa}}</span><UBadge variant="subtle">Confianza {{c.confianza}}</UBadge></div></UCard><UCard><template #header><h2 class="font-semibold">Riesgos y recomendación inmediata</h2></template><ul class="list-disc space-y-2 pl-5"><li v-for="r in consulta.respuesta.riesgos" :key="r">{{r}}</li></ul><p class="mt-4 rounded-lg bg-primary/10 p-4 font-medium">{{consulta.respuesta.recomendacion_inmediata}}</p></UCard><UCard><template #header><h2 class="font-semibold">Información para el mecánico</h2></template><p>{{consulta.respuesta.observaciones_mecanico}}</p><div class="mt-4"><p class="font-medium">Preguntas adicionales</p><ul class="mt-2 list-disc pl-5"><li v-for="p in consulta.respuesta.preguntas_adicionales" :key="p">{{p}}</li></ul></div></UCard></div><aside class="space-y-6"><UCard><template #header><h2 class="font-semibold">Continuar atención</h2></template><p><strong>Especialidad:</strong> {{consulta.especialidad||consulta.respuesta.especialidad_recomendada}}</p><p class="mt-3 text-sm text-muted">Servicios sugeridos:</p><div class="mt-2 flex flex-wrap gap-1"><UBadge v-for="s in consulta.respuesta.servicios_sugeridos" :key="s" variant="subtle">{{s}}</UBadge></div><template #footer><UButton v-if="!consulta.citaId&&can('citas.crear')" block label="Agendar cita" icon="i-lucide-calendar-plus" @click="router.visit(route('citas.create',{consultaIa:consulta.id}))"/><UButton v-else-if="consulta.citaId" block color="neutral" variant="outline" label="Consulta vinculada a cita" disabled/></template></UCard><UCard v-if="can('ia.revisar')&&!['confirmada','modificada','descartada','cerrada'].includes(consulta.estado)"><template #header><h2 class="font-semibold">Revisión humana</h2></template><form class="space-y-4" @submit.prevent="revisar"><UFormField label="Decisión"><USelect v-model="revision.estado" class="w-full" :items="[{label:'Confirmar',value:'confirmada'},{label:'Modificar',value:'modificada'},{label:'Descartar',value:'descartada'},{label:'Iniciar revisión',value:'en_revision'}]"/></UFormField><UFormField v-if="revision.estado==='modificada'" label="Resumen ajustado" required><UTextarea v-model="revision.resumenAjustado" class="w-full"/></UFormField><UFormField label="Observaciones" :required="['modificada','descartada'].includes(revision.estado)"><UTextarea v-model="revision.observaciones" class="w-full"/></UFormField><UButton type="submit" block label="Registrar revisión"/></form></UCard></aside></div></template></UDashboardPanel></template>
